#!/usr/bin/env node
// Root-executed metadata application only. Never invokes hashes, gates or runtime controls.
import fs from 'node:fs';
import path from 'node:path';
const args=process.argv.slice(2),allowed=new Set(['--run','--proposal','--apply']);
for(let i=0;i<args.length;i++){if(!allowed.has(args[i]))throw Error('Unknown argument '+args[i]);if(args[i]!=='--apply')i++;}
const value=f=>args[args.indexOf(f)+1],run=value('--run'),proposal=value('--proposal');
if(!args.includes('--apply')||!args.includes('--run')||!args.includes('--proposal')||!run||!proposal)throw Error('Usage: node /tmp/na-apply-final-ledgers.mjs --run RUN --proposal research/FINAL.json --apply');
const read=p=>fs.readFileSync(p,'utf8'),doc=JSON.parse(read(proposal));
if(doc.run!==run||doc.version!==2||doc.status!=='FINAL guarded proposal; root execution still required')throw Error('Not this run final proposal');
if(doc.alerts.length||doc.conflicts.length||doc.retainedOpen.length||doc.uncovered.length||doc.counts.uncoveredDeclaredEdges||doc.counts.historicalRowsRequiringRootTriage)throw Error('Proposal has unresolved holds');
if(doc.proposedInputs.length!==107||doc.counts.items!==2012||doc.currentDeclaredEdges.length!==1199)throw Error('Unexpected approved frontier size');
const guard=(includeLedgers=true)=>{for(const [group,files]of Object.entries(doc.applyGuards)){if(!includeLedgers&&group==='ledgerRawPreimages')continue;for(const [p,raw]of Object.entries(files)){if((fs.existsSync(p)?read(p):null)!==raw)throw Error('Guard changed '+p);}}};
guard();
const owns=new Map();for(const [p,raw]of Object.entries(doc.applyGuards.ownedManifestRawPreimages)){const batch=p.match(/-batch-(\d+)\.pages\.json$/)?.[1];for(const page of JSON.parse(raw)){owns.set('page:'+page.id,batch);for(const it of page.items)owns.set('item:'+(typeof it==='string'?it:it.id),batch);}}
const keys=new Map(),changes=[];
for(const input of doc.proposedInputs){if(!/^\d+$/.test(input.batch)||input.file!==`research/${run}-batch-${input.batch}.cross-batch-dependencies.json`||!Object.hasOwn(doc.applyGuards.ledgerRawPreimages,input.file))throw Error('Unapproved write target');const seen=new Set();for(const row of input.rows){const k=JSON.stringify([row.kind,row.consumer,row.supplier]);if(!['item','page'].includes(row.kind)||!['verified','removed'].includes(row.status)||owns.get(row.kind+':'+row.consumer)!==input.batch||typeof row.supplier!=='string'||!row.supplier||typeof row.evidence!=='string'||!row.evidence.trim()||seen.has(k))throw Error('Invalid projected row '+k);seen.add(k);keys.set(k,row);}const text=JSON.stringify(input.rows,null,2)+'\n';if(text!==doc.applyGuards.ledgerRawPreimages[input.file])changes.push({...input,text});}
for(const edge of doc.currentDeclaredEdges)if(keys.get(JSON.stringify([edge.kind,edge.consumer,edge.supplier]))?.status!=='verified')throw Error('Unclosed declared edge');
const archive=proposal.replace(/\.json$/,'')+'-before';if(fs.existsSync(archive))throw Error('Archive already exists; do not overwrite historical application');
fs.mkdirSync(archive);fs.mkdirSync(path.join(archive,'originals'));fs.mkdirSync(path.join(archive,'prepared'));
fs.writeFileSync(path.join(archive,'proposal.json'),read(proposal));
for(const [p,raw]of Object.entries(doc.applyGuards.ledgerRawPreimages))if(raw!==null)fs.writeFileSync(path.join(archive,'originals',path.basename(p)),raw);
fs.writeFileSync(path.join(archive,'original-absence.json'),JSON.stringify(Object.entries(doc.applyGuards.ledgerRawPreimages).filter(([,raw])=>raw===null).map(([p])=>p),null,2)+'\n');
for(const change of changes)fs.writeFileSync(path.join(archive,'prepared',path.basename(change.file)),change.text);
guard();
const applied=[];try{for(const change of changes){const raw=fs.existsSync(change.file)?read(change.file):null;if(raw!==doc.applyGuards.ledgerRawPreimages[change.file])throw Error('Ledger changed before write '+change.file);fs.renameSync(path.join(archive,'prepared',path.basename(change.file)),change.file);applied.push(change.file);}guard(false);for(const change of changes)if(read(change.file)!==change.text)throw Error('Post-write content mismatch '+change.file);const result={run,proposal,archive,at:new Date().toISOString(),status:'applied-current-owner-review-metadata-only',changed:applied,counts:doc.counts,notPerformed:['hashes','readiness','gates','runtime controls','native verdict mutation']};fs.writeFileSync(path.join(archive,'application.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));}catch(error){fs.writeFileSync(path.join(archive,'application-failure.json'),JSON.stringify({run,proposal,at:new Date().toISOString(),applied,error:String(error),historyPreserved:true},null,2)+'\n');throw error;}
